  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.salesforceAccountId).toBe('001XX000003DGHY2AO')
    expect(result.created).toBe(false)
  })
})

describe('handle', () => {
  it('maps fields correctly and sends PATCH to Salesforce', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH')
      expect(req.url).toBe('https://test.my.salesforce.com/services/data/v68.0/sobjects/Account/Website/acme.com')
      expect(req.headers.get('authorization')).toBe('Bearer test-token')
      expect(req.json).toEqual({
        Name: 'Acme Corp Deal',
        Website: 'acme.com',
        Deal_ID__c: '12345'
      })
      return jsonResponse({ id: '001XX000003DGHY2AO', success: true, errors: [], created: true }, 200)
    })

    const payload: HubSpotDealPayload = {
      dealId: '12345',
      dealname: 'Acme Corp Deal',
      domain: 'acme.com'
    }

    const result = await handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })

    expect(result.salesforceAccountId).toBe('001XX000003DGHY2AO')
    expect(result.created).toBe(true)
    expect(calls.length).toBe(1)
  })

  it('uses properties.dealname and properties.domain when top-level fields missing', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: '001XX000003DGHY2AO', success: true, errors: [], created: false }, 200))

    const payload: HubSpotDealPayload = {
      dealId: '12345',
      dealname: '',
      domain: '',
      properties: {
        dealname: 'From Properties',
        domain: 'from-props.com'
      }
    }

    // This should throw because dealname and domain are empty strings (falsy)
    await expect(handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })).rejects.toThrow('Missing required field: dealname')
  })

  it('throws on missing dealId', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { dealId: '', dealname: 'Test', domain: 'test.com' } as HubSpotDealPayload
    await expect(handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })).rejects.toThrow('Missing required field: dealId')
  })

  it('throws on missing dealname', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { dealId: '1', dealname: '', domain: 'test.com' } as HubSpotDealPayload
    await expect(handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })).rejects.toThrow('Missing required field: dealname')
  })

  it('throws on missing domain', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { dealId: '1', dealname: 'Test', domain: '' } as HubSpotDealPayload
    await expect(handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })).rejects.toThrow('Missing required field: domain')
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: HubSpotDealPayload = { dealId: '1', dealname: 'Test', domain: 'test.com' }
    await expect(handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })).rejects.toThrow('Salesforce upsert failed: 401 Unauthorized for PATCH https://test.my.salesforce.com/services/data/v68.0/sobjects/Account/Website/test.com')
    expect(calls.length).toBe(1)
  })

  it('throws when Salesforce returns success=false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ id: '', success: false, errors: [{ message: 'Duplicate Website' }], created: false }, 200))
    const payload: HubSpotDealPayload = { dealId: '1', dealname: 'Test', domain: 'test.com' }
    await expect(handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })).rejects.toThrow('Salesforce upsert returned success=false: [{"message":"Duplicate Website"}]')
  })

  it('encodes domain in URL correctly', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://test.my.salesforce.com/services/data/v68.0/sobjects/Account/Website/acme%2Ecom')
      return jsonResponse({ id: '001XX000003DGHY2AO', success: true, errors: [], created: false }, 200)
    })

    const payload: HubSpotDealPayload = { dealId: '1', dealname: 'Test', domain: 'acme.com' }
    await handle(payload, {
      salesforceInstance: 'test.my.salesforce.com',
      salesforceAccessToken: 'test-token',
      fetch
    })
    expect(calls.length).toBe(1)
  })
})

