export interface ConnectorConfig {
  /** Salesforce instance host, e.g. 'mycompany.my.salesforce.com' */
  salesforceInstance: string
  /** Bearer token for Salesforce REST API */
  salesforceAccessToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface HubSpotDealPayload {
  dealId: string
  dealname: string
  domain: string
  properties?: {
    dealname?: string
    domain?: string
  }
}

export interface UpsertResult {
  salesforceAccountId: string
  created: boolean
}

async function handle(payload: HubSpotDealPayload, config: ConnectorConfig): Promise<UpsertResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.dealId) throw new Error('Missing required field: dealId')
  if (!payload.dealname) throw new Error('Missing required field: dealname')
  if (!payload.domain) throw new Error('Missing required field: domain')

  const domain = payload.domain
  const dealName = payload.dealname
  const dealId = payload.dealId

  // Build Salesforce upsert URL using Website as external ID
  const url = `https://${config.salesforceInstance}/services/data/v68.0/sobjects/Account/Website/${encodeURIComponent(domain)}`

  const body = {
    Name: dealName,
    Website: domain,
    Deal_ID__c: dealId
  }

  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${config.salesforceAccessToken}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`Salesforce upsert failed: ${response.status} ${response.statusText} for PATCH ${url}`)
  }

  const result = await response.json() as { id: string; created: boolean; success: boolean; errors?: unknown[] }

  if (!result.success) {
    const errorMsg = result.errors ? JSON.stringify(result.errors) : 'Unknown error'
    throw new Error(`Salesforce upsert returned success=false: ${errorMsg}`)
  }

  return {
    salesforceAccountId: result.id,
    created: result.created
  }
}

